// Fifth evaluation, AC-312: letters no font has typed together with letters some font has, plus the single-letter cases.
// Sizes: 1280x800, 390x844 (touch), 320x640 (touch). Reports the hint (text, buttons, place, clipping), the screen-reader status,
// how long Enter takes and what its message names. OWN=1 then adds a font file from "Use your own font" and leaves the box.
const { chromium, BASE, log, SHOTS, FX } = require("./lib.cjs"); const { install, state } = require("./st.cjs");
const SIZES = { 1280: { viewport: { width: 1280, height: 800 } }, 390: { viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true }, 320: { viewport: { width: 320, height: 640 }, hasTouch: true, isMobile: true } };
const TEXTS = (process.env.TEXTS ? JSON.parse(process.env.TEXTS) : [" ř ⸘", " ⸘ ř", " Ω ⸘", " ⸘ ⸙", " नया ⸘ ok", " ř ⸘ Ω ⸙", " ř", " ⸘", " Ω"]);
const LINES = [[FX + "chrome-justified-mixed.pdf", /^in full/, "embedded"], [process.env.FXD + "/ac283-named-only.pdf", 0, "arial-named"]];
(async () => { const browser = await chromium.launch({ proxy: { server: process.env.HTTPS_PROXY } });
  for (const tag of (process.env.SIZES || "1280,390,320").split(",")) for (const [file, which, label] of LINES) for (const txt of TEXTS) {
    if (process.env.ONLY && !label.includes(process.env.ONLY)) continue;
    const phone = tag !== "1280"; const ctx = await browser.newContext({ deviceScaleFactor: 2, acceptDownloads: true, ...SIZES[tag] }); const page = await ctx.newPage(); const reqs = []; page.on("request", (r) => reqs.push({ t: Date.now(), m: r.method(), u: r.url() }));
    await page.goto(BASE + "/edit-pdf", { waitUntil: "networkidle", timeout: 90000 }); await page.locator('input[type="file"]').first().setInputFiles(file); await page.waitForTimeout(4000); await install(page);
    const o = typeof which === "number" ? page.getByTestId("line").nth(which) : page.getByRole("option", { name: which }); await o.scrollIntoViewIfNeeded().catch(() => {}); const b = await o.boundingBox();
    phone ? await page.touchscreen.tap(b.x + b.width - 3, b.y + b.height / 2) : await page.mouse.click(b.x + b.width - 3, b.y + b.height / 2); await page.getByTestId("line-input").waitFor(); await page.waitForTimeout(600); await page.keyboard.press("End");
    const tT = Date.now(); await page.keyboard.insertText(txt); let hintMs = null, s = null, prev = "";
    for (let k = 0; k < 100; k++) { s = await state(page); const cur = JSON.stringify(s.hint && [s.hint.text, s.hint.btns]); if (cur !== prev) { prev = cur; hintMs = Date.now() - tT; } await page.waitForTimeout(50); }
    const geo = await page.evaluate(() => { const h = document.querySelector("[data-testid=line-missing]"); if (!h) return null; const r = h.getBoundingClientRect(); const clipped = [h, ...h.querySelectorAll("*")].filter((e) => e.scrollWidth > e.clientWidth + 1 && getComputedStyle(e).overflowX !== "visible").map((e) => (e.textContent || "").slice(0, 30) + " " + e.scrollWidth + ">" + e.clientWidth); const outside = [...h.querySelectorAll("button, span")].filter((e) => { const q = e.getBoundingClientRect(); return q.width > 0 && (q.right > innerWidth + 0.5 || q.left < -0.5); }).map((e) => e.textContent.slice(0, 20)); const dock = document.querySelector("[data-testid=tool-dock], nav[aria-label], .ed-dock"); return { r: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)], vw: innerWidth, clipped, outside, rows: new Set([...h.querySelectorAll("button")].map((e) => Math.round(e.getBoundingClientRect().top))).size, labels: [...h.querySelectorAll("button")].map((e) => (e.getAttribute("aria-label") || "") + "|" + (e.getAttribute("title") || "")), scrollX: scrollX, docW: document.documentElement.scrollWidth }; });
    log(tag, label, JSON.stringify(txt), "typed:", JSON.stringify({ hintSettledMs: hintMs, missing: s.box.missing, under: s.box.under, hl: s.hl, hint: s.hint && s.hint.text, btns: s.hint && s.hint.btns, status: s.status, live: s.live, focused: s.box.focused, geo }));
    const nm = txt.trim().replace(/\s/g, "_"); await page.screenshot({ path: SHOTS + `ac312-${label}-${nm}-typed-${tag}.png` });
    await page.keyboard.press("Enter"); const t0 = Date.now(); let ans = null, last = "", tl = [];
    while (Date.now() - t0 < 9000) { const st = await state(page); const saved = !st.box && st.lines.some((l) => l.endsWith(txt.slice(-3))); const k = JSON.stringify({ box: !!st.box, notice: st.notice && st.notice.text.slice(0, 200), saved }); if (k !== last) { tl.push("+" + (Date.now() - t0) + " " + k); last = k; } if (ans == null && (st.notice || saved)) ans = Date.now() - t0; if (ans != null && Date.now() - t0 > ans + 1200) break; await page.waitForTimeout(25); }
    const s2 = await state(page); const snap = await page.locator("body").ariaSnapshot(); const sr = snap.split("\n").filter((x) => /status|alert|No font|draws|isn’t|Using|has no/.test(x)).map((x) => x.trim()).join(" || ").slice(0, 600);
    log(tag, label, JSON.stringify(txt), "Enter answered ms", ans, tl.join("  "), "| after:", JSON.stringify({ box: s2.box && s2.box.text.slice(-12), focused: s2.box && s2.box.focused, hint: s2.hint && s2.hint.text, btns: s2.hint && s2.hint.btns, noticeBtns: s2.notice && s2.notice.btns, status: s2.status }), "| aria:", sr);
    await page.screenshot({ path: SHOTS + `ac312-${label}-${nm}-enter-${tag}.png` });
    log(tag, label, JSON.stringify(txt), "font files fetched", JSON.stringify([...new Set(reqs.filter((r) => /woff/.test(r.u)).map((r) => r.u.split("/fonts/")[1]))]), "non-GET", reqs.filter((r) => r.m !== "GET").length);
    if (process.env.OWN === "1" && s2.box) {
      const own = page.getByRole("button", { name: /own font|Your font/ }).first(); const n0 = reqs.length; const fc = page.waitForEvent("filechooser", { timeout: 6000 }).catch(() => null); phone ? await own.tap().catch((e) => log("tap err", String(e).slice(0, 120))) : await own.click().catch((e) => log("click err", String(e).slice(0, 120))); const ch = await fc;
      if (!ch) log(tag, label, "own: NO file chooser"); else { await ch.setFiles(process.env.FXD + "/own-dejavu.ttf"); const tO = Date.now(); let s3, at = null; for (let k = 0; k < 80; k++) { s3 = await state(page); if (s3.hint && s3.hint.btns.some((x) => /DejaVu/.test(x))) { at = Date.now() - tO; break; } if (!s3.hint && !s3.box) break; await page.waitForTimeout(50); }
        await page.waitForTimeout(800); s3 = await state(page); log(tag, label, JSON.stringify(txt), "own font added: offered after ms", at, JSON.stringify({ box: !!s3.box, focused: s3.box && s3.box.focused, hint: s3.hint && s3.hint.text, btns: s3.hint && s3.hint.btns, status: s3.status, notice: s3.notice && s3.notice.text.slice(0, 160) }), "requests after pick (non-GET)", reqs.slice(n0).filter((r) => r.m !== "GET").length);
        await page.screenshot({ path: SHOTS + `ac312-${label}-${nm}-own-${tag}.png` });
        if (s3.box) { await page.locator("[data-testid=line-input]").focus(); await page.keyboard.press("Enter"); await page.waitForTimeout(2500); } const s4 = await state(page); log(tag, label, JSON.stringify(txt), "after own font + Enter:", JSON.stringify({ box: !!s4.box, saved: s4.lines.some((l) => l.endsWith(txt.slice(-3))), notice: s4.notice && s4.notice.text.slice(0, 200) }));
        if (!s4.box) { const dl = page.waitForEvent("download", { timeout: 8000 }).catch(() => null); await page.getByTestId("download").click(); const d = await dl; if (d) await d.saveAs(`out/s312n-${label}-${nm}-${tag}.pdf`); else log("no download"); } } }
    await ctx.close(); }
  await browser.close();
})().catch((e) => { console.error(String(e).slice(0, 1200)); process.exit(1); });
